#!/usr/bin/env python3
"""Generate menu clue names from minecraft-data 1.19.4 (MIT)."""
import hashlib, json, sys, urllib.request
from pathlib import Path
raw = Path(sys.argv[1]).read_bytes() if len(sys.argv)>1 else urllib.request.urlopen(
    'https://raw.githubusercontent.com/PrismarineJS/minecraft-data/master/data/pc/1.19.4/enchantments.json', timeout=30).read()
entries = json.loads(raw)
names = ['Unknown enchantment'] * (max(e['id'] for e in entries)+1)
for entry in entries:
    names[entry['id']] = entry['displayName']
Path('src/enchantment_data.inc').write_text(
    '/* Generated by tools/enchantments.py; minecraft-data MIT, see vendor/MINECRAFT-DATA-LICENSE. */\n'
    '/* source SHA256 ' + hashlib.sha256(raw).hexdigest() + ' */\n'
    'static const char *const enchantment_names[] = {\n' + ''.join(json.dumps(n)+',\n' for n in names) + '};\n')
